package it.frociart.app;
import android.app.Activity;import android.graphics.Typeface;import android.text.*;import android.view.*;import android.view.inputmethod.EditorInfo;import android.widget.*;import java.util.*;import java.util.function.Consumer;
/** A live, bounded watch list evaluated only from frozen inspection frames. */
final class FlowWatchPanel {
 final Ui.Sheet sheet;final EditText expression;final Ui.Button add,newExpression,step,play;final TextView frame,status;final ListView list;
 private final Activity owner;private final FlowVariablePanel.Host host;private final FlowWatchExpressions.Session session;private final Consumer<String> copy;private final Rows adapter=new Rows();private final Set<Ui.Sheet> children=new LinkedHashSet<>();private final TextView expressionLabel;private final LinearLayout controls,expressionRow;
 private FlowInspectExpression.Context context;private boolean paused,closed,compactInput;private int revision=-1,editing=-1;private List<FlowWatchExpressions.Row> rows=Collections.emptyList();
 FlowWatchPanel(Activity owner,Ui.Sheet sheet,FlowVariablePanel.Host host,FlowWatchExpressions.Session session,Consumer<String> copy){
  this.owner=owner;this.sheet=sheet;this.host=host;this.session=session;this.copy=copy;
  editing=session.draftIndex>=0&&session.draftIndex<session.expressions().size()?session.draftIndex:-1;
  LinearLayout form=Ui.column(owner);frame=Ui.note(owner,"");form.addView(frame);expressionLabel=Ui.text(owner,"ESPRESSIONE DA OSSERVARE",11,true);form.addView(expressionLabel);expression=Ui.edit(owner,session.draft,"Esempio: v[i]",false);expression.setId(View.generateViewId());expressionLabel.setLabelFor(expression.getId());expression.setTag("watch-expression");expression.setContentDescription("Espressione da aggiungere o modificare nella lista osservata");expression.setFilters(new InputFilter[]{new InputFilter.LengthFilter(FlowWatchExpressions.MAX_LENGTH)});expression.setImeOptions(EditorInfo.IME_ACTION_DONE|EditorInfo.IME_FLAG_NO_EXTRACT_UI);if(session.selectionStart>=0&&session.selectionEnd>=0)expression.setSelection(Math.min(expression.length(),session.selectionStart),Math.min(expression.length(),session.selectionEnd));expressionRow=Ui.actionRow(owner);expressionRow.setBaselineAligned(false);expressionRow.addView(expression,Ui.weight(owner,-2));add=button(editing<0?"Osserva":"Salva modifica",1);add.setTag("watch-add");add.setMaxWidth(Ui.dp(owner,160));add.setMinimumHeight(Ui.dp(owner,52));add.setOnClickListener(v->put());expressionRow.addView(add,new LinearLayout.LayoutParams(-2,-2));form.addView(expressionRow,new LinearLayout.LayoutParams(-1,-2));newExpression=button(editing<0?"Nuova":"Annulla modifica",0);newExpression.setTag("watch-new");newExpression.setContentDescription("Annulla la bozza di modifica e scrivi una nuova espressione. La lista resta invariata.");newExpression.setOnClickListener(v->newExpression());LinearLayout.LayoutParams newSize=new LinearLayout.LayoutParams(-1,-2);newSize.topMargin=Ui.dp(owner,8);form.addView(newExpression,newSize);updateAddAction();sheet.fixed(form);sheet.root.getViewTreeObserver().addOnGlobalLayoutListener(keyboardLayout);
  sheet.paragraph("Fino a 8 espressioni, aggiornate in pausa nella chiamata scelta. La lista resta in questa sessione del progetto; non è salvata nel file.");status=Ui.note(owner,"");status.setTag("watch-status");status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);sheet.body.addView(status);
  list=new ListView(owner);list.setTag("watch-list");list.setDivider(null);list.setContentDescription("Espressioni osservate. Tocca una voce per leggere, modificare o rimuovere.");list.setNestedScrollingEnabled(true);list.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN)v.getParent().requestDisallowInterceptTouchEvent(true);else if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL)v.getParent().requestDisallowInterceptTouchEvent(false);return false;});list.setAdapter(adapter);list.setOnItemClickListener((p,v,at,id)->showRow(at));sheet.body.addView(list,new LinearLayout.LayoutParams(-1,Ui.dp(owner,280)));
  controls=Ui.row(owner);step=button("Avanti",0);play=button("Riprendi",1);step.setTag("watch-step");play.setTag("watch-play");step.setOnClickListener(v->{host.step();});play.setOnClickListener(v->{host.play();});controls.addView(step,Ui.weight(owner,-2));controls.addView(play,Ui.weight(owner,-2));sheet.footer.addView(controls);
  expression.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int n){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){session.draft=s.toString();}});expression.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_DONE||event!=null&&event.getKeyCode()==KeyEvent.KEYCODE_ENTER&&event.getAction()==KeyEvent.ACTION_DOWN){put();return true;}return false;});
 }
 private final ViewTreeObserver.OnGlobalLayoutListener keyboardLayout=this::keyboard;
 private void keyboard(){if(closed)return;android.graphics.Rect visible=new android.graphics.Rect();sheet.root.getWindowVisibleDisplayFrame(visible);boolean ime;if(android.os.Build.VERSION.SDK_INT>=30){WindowInsets insets=sheet.dialog.getWindow().getDecorView().getRootWindowInsets();ime=insets!=null&&insets.isVisible(WindowInsets.Type.ime());}else ime=owner.getResources().getDisplayMetrics().heightPixels-visible.height()>Ui.dp(owner,100);boolean compact=ime&&visible.height()<Ui.dp(owner,330);int vertical=Ui.dp(owner,compact?6:14),minimum=Ui.dp(owner,compact?52:54);if(expression.getPaddingTop()!=vertical||expression.getPaddingBottom()!=vertical||expression.getMinimumHeight()!=minimum){expression.setPadding(expression.getPaddingLeft(),vertical,expression.getPaddingRight(),vertical);expression.setMinimumHeight(minimum);}sheet.compactHeader(compact);sheet.hideHeadingForInput(ime&&visible.height()<Ui.dp(owner,200));if(compactInput!=compact){compactInput=compact;updateAddAction();}int state=compact?View.GONE:View.VISIBLE;frame.setVisibility(state);newExpression.setVisibility(state);expressionLabel.setVisibility(View.VISIBLE);sheet.scroll.setVisibility(state);controls.setVisibility(state);}
 private void updateAddAction(){String label=editing<0?"Osserva":"Salva modifica";add.setLabel(compactInput?"":label);add.setIcon(compactInput?"check":null);add.setContentDescription(label+" espressione osservata");add.setTooltipText(label);ViewGroup.LayoutParams size=add.getLayoutParams();int width=compactInput?Ui.dp(owner,52):-2,height=compactInput?Ui.dp(owner,52):-2;if(size.width!=width||size.height!=height){size.width=width;size.height=height;add.setLayoutParams(size);}}
 void keepDraft(){session.draft=expression.getText().toString();session.draftIndex=editing;session.selectionStart=expression.getSelectionStart();session.selectionEnd=expression.getSelectionEnd();}
 private Ui.Button button(String text,int tone){Ui.Button b=new Ui.Button(owner,text,null,tone);b.setSingleLine(false);b.setMaxLines(3);b.setEllipsize(null);b.setMinimumHeight(Ui.dp(owner,48));return b;}
 void update(FlowInspectExpression.Context value,boolean paused,boolean canStep,boolean canPlay){if(closed)return;boolean changed=context!=value||this.paused!=paused||revision!=session.revision();context=value;this.paused=paused;frame.setText(value==null?(paused?"Nessuna chiamata disponibile":"In esecuzione · aggiornamento alla pausa"):value.functionName+" · passo "+value.steps+" · valori in pausa");step.setEnabled(canStep);play.setEnabled(canPlay);play.setLabel(host.running()?"Pausa":"Riprendi");if(changed)render();}
 void put(){if(closed)return;try{session.put(expression.getText().toString(),editing);editing=-1;expression.setText("");updateAddAction();newExpression.setLabel("Nuova");expression.setError(null);status.setTextColor(Ui.muted());status.setText("Espressione conservata per questa sessione del progetto.");Ui.dismissKeyboard(expression);render();}catch(IllegalArgumentException ex){expression.setError(ex.getMessage());expression.requestFocus();}}
 void newExpression(){if(closed)return;boolean edited=editing>=0;editing=-1;session.draftIndex=session.selectionStart=session.selectionEnd=-1;expression.setText("");expression.setError(null);updateAddAction();newExpression.setLabel("Nuova");status.setTextColor(Ui.muted());status.setText(edited?"Modifica annullata. La lista è invariata.":"Scrivi una nuova espressione. La lista è invariata.");expression.requestFocus();}
 private void render(){rows=FlowWatchExpressions.read(session,context,paused);revision=session.revision();adapter.notifyDataSetChanged();list.setVisibility(rows.isEmpty()?View.GONE:View.VISIBLE);if(rows.isEmpty())status.setText("Scrivi un’espressione per iniziare la lista.");int width=list.getWidth()>0?list.getWidth():Math.min(owner.getResources().getDisplayMetrics().widthPixels,Ui.dp(owner,640))-Ui.dp(owner,40),height=0,maximum=Ui.dp(owner,320);for(int i=0;i<rows.size()&&height<maximum;i++){View row=adapter.getView(i,null,list);row.measure(View.MeasureSpec.makeMeasureSpec(Math.max(1,width),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));height+=row.getMeasuredHeight();}ViewGroup.LayoutParams size=list.getLayoutParams();size.height=Math.max(1,Math.min(maximum,height));list.setLayoutParams(size);}
 private void showRow(int index){if(closed||index<0||index>=rows.size())return;FlowWatchExpressions.Row row=rows.get(index);Ui.Sheet detail=new Ui.Sheet(owner,"Espressione osservata",context==null?null:context.functionName+" · passo "+context.steps);children.add(detail);detail.dialog.setOnDismissListener(d->children.remove(detail));TextView source=Ui.text(owner,row.expression,15,true);source.setTextIsSelectable(true);source.setTypeface(Typeface.MONOSPACE);detail.body.addView(source);TextView value=Ui.text(owner,row.result==null?row.preview:FlowInspectExpression.readable(row.result),15,false);value.setTextIsSelectable(true);value.setTag("watch-full-value");detail.body.addView(value);if(row.result!=null&&!row.result.note.isEmpty())detail.paragraph(row.result.note);
  detail.action("Modifica","edit",0,()->{detail.dismiss();editing=index;expression.setText(session.expressions().get(index));updateAddAction();newExpression.setLabel("Annulla modifica");expression.requestFocus();expression.setSelection(expression.length());});detail.action("Rimuovi","delete",0,()->{detail.dismiss();session.remove(index);if(editing==index){editing=-1;expression.setText("");updateAddAction();newExpression.setLabel("Nuova");}else if(editing>index)editing--;render();});if(row.result!=null&&row.result.copyText!=null)detail.action("Copia risultato","copy",0,()->{try{if(row.result.copyText.length()>32768)throw new IllegalArgumentException();copy.accept(row.result.copyText);status.setText("Risultato copiato.");detail.dismiss();}catch(RuntimeException ex){detail.paragraph("Non riesco a copiare questo risultato. Puoi selezionare il testo.");}});detail.show();
 }
 void close(){if(closed)return;keepDraft();closed=true;if(sheet.root.getViewTreeObserver().isAlive())sheet.root.getViewTreeObserver().removeOnGlobalLayoutListener(keyboardLayout);for(Ui.Sheet child:new ArrayList<>(children))child.dismissNow();children.clear();rows=Collections.emptyList();context=null;adapter.notifyDataSetChanged();Ui.dismissKeyboard(expression);}
 private final class Rows extends BaseAdapter{public int getCount(){return rows.size();}public Object getItem(int at){return rows.get(at);}public long getItemId(int at){return at;}public View getView(int at,View reused,ViewGroup parent){Ui.Choice v=reused instanceof Ui.Choice?(Ui.Choice)reused:new Ui.Choice(owner);FlowWatchExpressions.Row row=rows.get(at);v.setClickable(false);v.setFocusable(false);v.bind(row.expression,row.preview,row.error==null?Ui.accentInk():Ui.danger());return v;}}
}
